/** Tests for BATCH-28 frontend auth API (TEST-28-02-01, 02, 05, 06, 08). */

import { describe, it, expect, vi, beforeEach } from "vitest";

// Mock the client module
const mockFetch = vi.fn();
vi.mock("@/api/client", () => ({
  apiFetch: (...args: unknown[]) => mockFetch(...args),
}));

import { register, login, getMe, listUsers } from "@/api/auth";

describe("auth API", () => {
  beforeEach(() => {
    mockFetch.mockReset();
  });

  it("TEST-28-02-02: login calls API with correct params", async () => {
    const mockResponse = {
      token: "jwt-token-123",
      user: { id: 1, username: "alice", email: "alice@test.com", role: "user" },
    };
    mockFetch.mockResolvedValue(mockResponse);

    const result = await login("alice", "password123");

    expect(mockFetch).toHaveBeenCalledWith("/auth/login", {
      method: "POST",
      body: JSON.stringify({ username: "alice", password: "password123" }),
    });
    expect(result.token).toBe("jwt-token-123");
    expect(result.user.username).toBe("alice");
  });

  it("TEST-28-02-05: login success returns token", async () => {
    const mockResponse = {
      token: "jwt-token-456",
      user: { id: 2, username: "bob", email: "bob@test.com", role: "user" },
    };
    mockFetch.mockResolvedValue(mockResponse);

    const result = await login("bob", "secret");
    expect(result.token).toBe("jwt-token-456");
  });

  it("TEST-28-02-06: login error throws", async () => {
    mockFetch.mockRejectedValue(new Error("Invalid credentials"));

    await expect(login("bob", "wrong")).rejects.toThrow("Invalid credentials");
  });

  it("TEST-28-02-08: register calls API with correct params", async () => {
    const mockResponse = {
      token: "jwt-token-789",
      user: { id: 3, username: "charlie", email: "charlie@test.com", role: "user" },
    };
    mockFetch.mockResolvedValue(mockResponse);

    const result = await register("charlie", "charlie@test.com", "pass123");

    expect(mockFetch).toHaveBeenCalledWith("/auth/register", {
      method: "POST",
      body: JSON.stringify({
        username: "charlie",
        email: "charlie@test.com",
        password: "pass123",
      }),
    });
    expect(result.user.username).toBe("charlie");
    expect(result.user.role).toBe("user");
  });

  it("getMe calls correct endpoint", async () => {
    const mockUser = { id: 1, username: "alice", email: "alice@test.com", role: "user" };
    mockFetch.mockResolvedValue(mockUser);

    const result = await getMe();
    expect(mockFetch).toHaveBeenCalledWith("/auth/me");
    expect(result.username).toBe("alice");
  });

  it("listUsers calls correct endpoint", async () => {
    const mockUsers = [
      { id: 1, username: "alice", email: "alice@test.com", role: "admin" },
    ];
    mockFetch.mockResolvedValue(mockUsers);

    const result = await listUsers();
    expect(mockFetch).toHaveBeenCalledWith("/auth/users");
    expect(result).toHaveLength(1);
  });
});

/** Tests for BATCH-28 auth context (TEST-28-02-03, 04, 07). */

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { BrowserRouter, MemoryRouter } from "react-router-dom";
import { AuthProvider, useAuth } from "@/contexts/auth-context";

// Mock the auth API
vi.mock("@/api/auth", () => ({
  login: vi.fn(),
  register: vi.fn(),
  getMe: vi.fn(),
}));

import { login as mockLogin, getMe as mockGetMe } from "@/api/auth";

function ShowAuth() {
  const { user, loading, login, logout } = useAuth();
  if (loading) return <div data-testid="loading">Loading</div>;
  return (
    <div>
      <span data-testid="user-state">{user ? user.username : "null"}</span>
      <button data-testid="login-btn" onClick={() => login("alice", "pass")}>
        Login
      </button>
      <button data-testid="logout-btn" onClick={logout}>
        Logout
      </button>
    </div>
  );
}

function renderWithProviders(ui: React.ReactElement) {
  return render(
    <BrowserRouter>
      <AuthProvider>{ui}</AuthProvider>
    </BrowserRouter>,
  );
}

describe("AuthContext", () => {
  beforeEach(() => {
    vi.mocked(mockGetMe).mockReset();
    vi.mocked(mockLogin).mockReset();
    localStorage.clear();
  });

  it("TEST-28-02-03: auth context provides user state", async () => {
    vi.mocked(mockLogin).mockResolvedValue({
      token: "test-token",
      user: { id: 1, username: "alice", email: "a@test.com", role: "user" },
    });

    renderWithProviders(<ShowAuth />);

    // Initially no user (getMe finds no token)
    await waitFor(() => {
      expect(screen.getByTestId("user-state").textContent).toBe("null");
    });

    // Login
    await userEvent.click(screen.getByTestId("login-btn"));

    await waitFor(() => {
      expect(screen.getByTestId("user-state").textContent).toBe("alice");
    });
  });

  it("TEST-28-02-07: logout clears token", async () => {
    vi.mocked(mockLogin).mockResolvedValue({
      token: "test-token",
      user: { id: 1, username: "alice", email: "a@test.com", role: "user" },
    });

    renderWithProviders(<ShowAuth />);

    // Login first
    await userEvent.click(screen.getByTestId("login-btn"));
    await waitFor(() => {
      expect(screen.getByTestId("user-state").textContent).toBe("alice");
    });

    // Logout
    await userEvent.click(screen.getByTestId("logout-btn"));
    await waitFor(() => {
      expect(screen.getByTestId("user-state").textContent).toBe("null");
    });

    // Token cleared from localStorage
    expect(localStorage.getItem("erock_jwt_token")).toBeNull();
  });

  it("restores user from stored token", async () => {
    localStorage.setItem("erock_jwt_token", "existing-token");
    vi.mocked(mockGetMe).mockResolvedValue({
      id: 1,
      username: "restored",
      email: "r@test.com",
      role: "admin",
    });

    renderWithProviders(<ShowAuth />);

    await waitFor(() => {
      expect(screen.getByTestId("user-state").textContent).toBe("restored");
    });
  });
});

